                data = [data]

            df = pd.DataFrame(data)
            df['Source'] = filename
            all_dfs.append(df)

        shutil.move(file_path, os.path.join(processed_dir, filename))

    if not all_dfs:
        return pd.DataFrame()

    return pd.concat(all_dfs, ignore_index=True)

